// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor1, address actor2) public {
        vm.assume(actor1 != address(0));
        vm.assume(actor2 != address(0));
        vm.assume(actor1 != actor2);

        vm.deal(actor1, 1 ether);
        vm.deal(actor2, 1 ether);

        BankHelper b1 = new BankHelper();
        BankHelper b2 = new BankHelper();

        vm.prank(address(b1));
        bool ok1;
        try c.airDrop() {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        if (!ok1) {
            assertTrue(c.tokenBalance(address(b1)) == 0);
            return;
        }

        vm.prank(address(b2));
        bool ok2;
        try c.airDrop() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(
            (ok1 && ok2 && c.tokenBalance(address(b1)) == 20 && c.tokenBalance(address(b2)) == 20)
            || (!ok1 && c.tokenBalance(address(b1)) == 0 && c.tokenBalance(address(b2)) == 0)
        );
    }
}

contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
